#!/usr/bin/env python3
"""Generate the six static labour service pages from reviewed page copy."""
from html import escape
from pathlib import Path
import json

ROOT = Path(__file__).resolve().parents[1] / "public"
BASE = "https://royramdaw.co.za"
template = (ROOT / "about/index.html").read_text()
shared_body_start = template[template.index("<body>"):template.index('<main id="main">')]
shared_body_start = shared_body_start.replace('aria-current="page" class="nav-link active" href="/about/"', 'class="nav-link" href="/about/"')
shared_body_start = shared_body_start.replace('class="nav-link" href="/practice-areas/"', 'aria-current="page" class="nav-link active" href="/practice-areas/"')
shared_body_end = template[template.index("</main>"):]
shared_body_end = shared_body_end.replace('href="/practice-areas/#labour"', 'href="/labour-employment-law/"')

LRA = "https://www.labour.gov.za/DocumentCenter/Acts/Labour%20Relations/Labour%20Relations%20Act.pdf"
CCMA = "https://www.ccma.org.za/wp-content/uploads/2025/07/CCMA-Rules-Info-Sheet-2025-01-1.pdf"
DISMISSAL = "https://www.ccma.org.za/wp-content/uploads/2025/08/Unfair-Dismissal-Disputes-info-sheet-2025-01.pdf"

# Each topic corresponds to a distinct service need already described on the
# existing practice-area page and in the client-supplied profile.
PAGES = [
    dict(slug="labour-employment-law", title="Labour & Employment Lawyers in Newcastle | Roy Ramdaw", description="Labour and employment law advice from Roy Ramdaw & Associates Inc. in Newcastle, KZN. Discuss workplace disputes, contracts, CCMA matters and court proceedings.", h1="Labour & Employment Law in Newcastle", intro="Roy Ramdaw & Associates Inc. assists employers and employees with South African workplace matters from its Newcastle head office. The existing practice includes employment disputes, disciplinary processes, CCMA and bargaining council matters, employment contracts and Labour Court proceedings. The first step is to identify the facts, the applicable forum and any urgent time limit.", sections=[("Advice across the employment relationship", "A dispute may begin before or after employment ends. The firm can assess contracts and workplace records, advise on disciplinary or grievance processes, and consider whether negotiation, a statutory referral or litigation is appropriate. The relevant process depends on the issue, the parties and any applicable bargaining council agreement.", ["Employment contracts and workplace obligations", "Unfair dismissal and unfair labour practice disputes", "Disciplinary processes, retrenchment and workplace investigations"]), ("Choosing a practical route", "South African labour disputes do not all follow the same path. Some matters are referred to the CCMA or a bargaining council; others may require a Labour Court application or review. The firm can help identify the correct forum and prepare the record needed to assess a matter. Legal representation at the CCMA is subject to its rules and the type of proceedings.", ["Review notices, contracts and correspondence", "Check referral dates and procedural requirements", "Discuss the available options and likely next steps"]), ("Local access and experience", "The firm’s head office is at 29 Bird Street, Newcastle, KwaZulu-Natal. Dr Anandroy Ramdaw’s published profile records experience as a CCMA commissioner and in Labour Court matters. The firm also has a Durban office; enquiries can start through the Newcastle contact details below.", [])], source=LRA),
    dict(slug="unfair-dismissal", title="Unfair Dismissal Attorney in Newcastle | Roy Ramdaw", description="Need advice after a dismissal in South Africa? Roy Ramdaw & Associates Inc. assesses unfair dismissal disputes, referral dates, evidence and the appropriate forum.", h1="Unfair Dismissal Advice and Representation", intro="A dismissal dispute calls for a prompt review of what happened, why employment ended and which process applies. Roy Ramdaw & Associates Inc. advises on unfair dismissal matters as part of its established employment practice. The firm can assess the documents and explain possible referral, conciliation, arbitration or court steps for the particular case.", sections=[("What needs to be assessed?", "The Labour Relations Act protects employees from unfair dismissal. A dispute may concern the reason for dismissal, the procedure followed, or both. The legal definition of dismissal also covers some less obvious situations, including certain fixed-term contract disputes and constructive dismissal. A legal assessment depends on the actual employment relationship and evidence.", ["Dismissal letter and stated reasons", "Contract, policies, hearing notices and minutes", "Messages, witness details and a dated sequence of events"]), ("Time limits and the right forum", "Under section 191 of the Labour Relations Act, a dispute about the fairness of a dismissal is generally referred within 30 days of dismissal or a later final decision to uphold it. Depending on sector and jurisdiction, referral may be to a bargaining council or the CCMA. Late referrals may need a condonation application; do not assume extra time will be granted.", ["Confirm the date from which time runs", "Check whether a bargaining council has jurisdiction", "Seek advice promptly if the deadline may have passed"]), ("How the firm can assist", "The firm can review the merits, prepare for conciliation, assess whether arbitration or Labour Court proceedings are appropriate and advise on possible remedies. Representation at a CCMA hearing is governed by the CCMA rules; an attorney’s ability to appear depends on the type of dispute and the commissioner’s ruling where required. No outcome can be promised.", [])], source=DISMISSAL),
    dict(slug="ccma-representation", title="CCMA Advice & Representation | Roy Ramdaw Newcastle", description="Get advice on CCMA referrals, conciliation and arbitration from Roy Ramdaw & Associates Inc. in Newcastle. Attorney representation depends on CCMA rules and the dispute.", h1="CCMA Advice and Representation", intro="The Commission for Conciliation, Mediation and Arbitration (CCMA) deals with many workplace disputes, but jurisdiction, time limits and representation rules vary. Roy Ramdaw & Associates Inc. assists with CCMA and bargaining council processes and can explain how those rules apply to a proposed referral or existing matter.", sections=[("Before and during conciliation", "An initial review should identify the dispute, the correct forum and the relevant deadline. The CCMA’s published rules explain how to serve and file a referral and what documents may be required. Conciliation seeks to resolve the dispute. Preparation can include a clear chronology, key records and a realistic view of possible settlement, even where an attorney may not appear at the hearing.", ["Check referral forms and proof of service", "Organise contracts, payslips, notices and correspondence", "Prepare the main facts and desired resolution"]), ("If the dispute remains unresolved", "Some disputes proceed to arbitration after a certificate of non-resolution or under a combined conciliation-arbitration process. Others are for the Labour Court. The firm can help assess the route, prepare evidence and submissions, and advise on the steps following an award or ruling. Statutory and rule-based time limits should be checked for the specific matter.", ["Identify the appropriate next forum", "Preserve documents and witness details", "Review the applicable deadlines and hearing notice"]), ("A note on attorney appearances", "Legal representation is not automatic at every CCMA stage. The CCMA rules place particular limits on attorney representation in some dismissal arbitrations; an agreement or commissioner’s permission may be required. Ask the firm to check the current rule and case category before assuming an attorney can appear.", [])], source=CCMA),
    dict(slug="retrenchment-employment-disputes", title="Retrenchment & Employment Disputes | Roy Ramdaw", description="Advice on retrenchment consultations and workplace disputes in South Africa from Roy Ramdaw & Associates Inc., Newcastle. Review notices, process and legal options.", h1="Retrenchment and Employment Disputes", intro="Retrenchment affects both the people whose jobs may end and the employers who must manage operational changes lawfully. Roy Ramdaw & Associates Inc. lists retrenchment and workplace disputes within its employment practice. The firm can review a proposed process or an existing dispute in light of the actual workplace facts.", sections=[("Consultation and process", "Section 189 of the Labour Relations Act requires a meaningful joint process when an employer contemplates dismissal for operational requirements. The parties should consider ways to avoid or minimise dismissals, selection methods and severance pay. The steps and participants can depend on collective agreements, unions and the scale of the proposed retrenchment.", ["Review the written notice and reasons", "Identify the correct consulting parties", "Consider alternatives, selection criteria and records of consultation"]), ("When a dispute arises", "Questions may concern whether the reason was genuine, whether consultation was fair, or whether the correct procedure and payments were followed. Other workplace disputes, including disciplinary and discrimination matters, have different legal tests and forums. The firm can help classify the issue and assess the available route without treating every dispute as an unfair dismissal claim.", ["Keep a dated record of meetings and proposals", "Retain relevant employment and payment documents", "Check the correct forum and any referral deadline"]), ("Advice for employers and employees", "The firm can assist with reviewing the process, drafting or responding to correspondence, negotiation and dispute proceedings where instructed. Early advice can clarify the immediate steps and help preserve the information needed for a later review.", [])], source=LRA),
    dict(slug="labour-court", title="Labour Court Attorney | Roy Ramdaw & Associates", description="Discuss Labour Court proceedings, reviews and employment litigation with Roy Ramdaw & Associates Inc. in Newcastle. The correct forum and deadlines depend on your dispute.", h1="Labour Court Proceedings", intro="The Labour Court deals with particular employment disputes and applications under South African labour legislation. Roy Ramdaw & Associates Inc. lists Labour Court and Labour Appeal Court litigation within its existing employment practice. A court route should be chosen only after checking jurisdiction, the procedural history and the applicable time limits.", sections=[("When court may be relevant", "Some disputes are referred to the Labour Court after statutory conciliation; other matters may involve a review of an arbitration award or an urgent application. A CCMA referral and a court claim are not interchangeable. The firm can examine the facts and advise whether a court process is available and proportionate.", ["Check the dispute type and jurisdiction", "Review referral forms, certificates and awards", "Identify the relief sought and procedural deadline"]), ("Preparing a case", "Court proceedings require a clear evidentiary record and compliance with rules for filing and service. The firm can advise on the relevant documents, draft or respond to pleadings and consider negotiation where suitable. A review is generally different from a fresh hearing on the merits.", ["Compile contracts, correspondence and decisions", "Preserve witness and hearing records", "Assess costs and practical objectives"]), ("Experience and enquiry", "Dr Anandroy Ramdaw’s published profile records Labour Court experience and prior CCMA commissioner work. Those credentials are described on the firm’s attorney page. Contact the Newcastle office to discuss whether the firm can assist with the specific court matter.", [])], source=LRA),
    dict(slug="employment-contracts-disciplinary", title="Employment Contracts & Disciplinary Advice | Roy Ramdaw", description="Employment contract reviews and disciplinary matter advice from Roy Ramdaw & Associates Inc. in Newcastle, KZN. Understand documents, process and possible dispute routes.", h1="Employment Contracts and Disciplinary Matters", intro="Clear employment terms and fair workplace processes can prevent avoidable disputes. Roy Ramdaw & Associates Inc. lists employment contracts, disciplinary proceedings and workplace investigations among its labour services. The firm can review the relevant documents and advise on a proportionate response for an employer or employee.", sections=[("Employment contracts", "Contracts may address duties, pay, working time, confidentiality, notice and dispute procedures. Their effect must be read with applicable legislation, collective agreements and workplace policies. The firm can review proposed terms or a disagreement about existing obligations and identify points needing clarification.", ["Check the signed contract and later variations", "Compare relevant policies and collective agreements", "Identify the disputed term and practical objective"]), ("Disciplinary processes", "A disciplinary issue may call for investigation, notice of allegations, an opportunity to respond and a reasoned decision. The applicable requirements depend on the facts and current law. The firm can advise on preparation, records, procedural fairness and what steps may follow an outcome. It should not be assumed that every hearing allows an outside attorney to appear.", ["Keep notices, evidence and hearing records", "Record dates and persons involved", "Seek advice before a time-sensitive response or referral"]), ("Where a dispute follows", "If a process ends in dismissal or another contested workplace decision, the forum and deadline depend on the claim. The firm can assess whether negotiation, an internal process, a bargaining council, the CCMA or litigation is appropriate.", [])], source=LRA),
]

related = [(p["slug"], p["h1"]) for p in PAGES]
for p in PAGES:
    url = f'{BASE}/{p["slug"]}/'
    title, description = escape(p["title"]), escape(p["description"])
    schema = {"@context":"https://schema.org","@graph":[
      {"@type":"LegalService","@id":f"{BASE}/#legal-service","name":"Roy Ramdaw & Associates Inc.","url":f"{BASE}/","telephone":"+27343127592","address":{"@type":"PostalAddress","streetAddress":"29 Bird Street","addressLocality":"Newcastle","addressRegion":"KwaZulu-Natal","addressCountry":"ZA"}},
      {"@type":"Service","@id":url+"#service","name":p["h1"],"description":p["description"],"provider":{"@id":f"{BASE}/#legal-service"},"areaServed":{"@type":"Country","name":"South Africa"},"mainEntityOfPage":{"@id":url}},
      {"@type":"BreadcrumbList","itemListElement":[{"@type":"ListItem","position":1,"name":"Home","item":f"{BASE}/"},{"@type":"ListItem","position":2,"name":"Practice Areas","item":f"{BASE}/practice-areas/"},{"@type":"ListItem","position":3,"name":p["h1"],"item":url}]}
    ]}
    head = f'''<!DOCTYPE html>\n<html lang="en-ZA"><head><meta charset="utf-8"/><meta name="viewport" content="width=device-width,initial-scale=1"/><meta name="theme-color" content="#0d345e"/><title>{title}</title><meta name="description" content="{description}"/><meta name="robots" content="index,follow,max-image-preview:large"/><link rel="canonical" href="{url}"/><meta property="og:title" content="{title}"/><meta property="og:description" content="{description}"/><meta property="og:type" content="website"/><meta property="og:url" content="{url}"/><meta property="og:image" content="{BASE}/assets/roy-ramdaw-social-preview-2026.jpg"/><meta property="og:image:width" content="1200"/><meta property="og:image:height" content="630"/><meta property="og:image:alt" content="Roy Ramdaw &amp; Associates Inc. logo alongside Dr Anandroy Ramdaw"/><meta name="twitter:card" content="summary_large_image"/><meta name="twitter:title" content="{title}"/><meta name="twitter:description" content="{description}"/><meta name="twitter:image" content="{BASE}/assets/roy-ramdaw-social-preview-2026.jpg"/><link rel="icon" type="image/png" href="/assets/favicon.png"/><link rel="preconnect" href="https://fonts.googleapis.com"/><link rel="preconnect" href="https://fonts.gstatic.com" crossorigin/><link rel="stylesheet" href="https://fonts.googleapis.com/css2?family=DM+Sans:wght@400;500;600;700&amp;family=Manrope:wght@400;500;600;700;800&amp;display=swap"/><link rel="stylesheet" href="/assets/site.css"/><script defer src="/assets/site.js"></script><script type="application/ld+json">{json.dumps(schema,ensure_ascii=False,separators=(',',':'))}</script></head>'''
    body = f'<main id="main"><section class="page-hero"><div class="container"><span class="eyebrow eyebrow-light">LABOUR &amp; EMPLOYMENT LAW</span><h1>{escape(p["h1"])}</h1><p>{escape(p["intro"])}</p></div></section>'
    body += '<section class="section"><div class="container legal-copy service-copy"><p><a class="text-link" href="/practice-areas/">← All practice areas</a></p>'
    for heading, paragraph, bullets in p["sections"]:
        body += f'<h2>{escape(heading)}</h2><p>{escape(paragraph)}</p>'
        if bullets: body += '<ul>'+''.join(f'<li>{escape(item)}</li>' for item in bullets)+'</ul>'
    body += f'<p><strong>Source:</strong> <a href="{p["source"]}" rel="noopener noreferrer" target="_blank">Official South African labour guidance and legislation ↗</a>. This is general information, not advice on a particular matter.</p>'
    body += '<p>Read about <a href="/managing-partner/">Dr Anandroy Ramdaw’s experience</a> or <a href="/insights/">browse legal insights</a>.</p></div></section>'
    body += '<section class="section cream"><div class="container"><div class="section-heading centered"><span class="eyebrow">RELATED EMPLOYMENT SERVICES</span><h2>Find the right starting point.</h2></div><div class="jump-chips">'
    body += ''.join(f'<a href="/{slug}/">{escape(name)}</a>' for slug,name in related if slug!=p["slug"])
    body += '</div></div></section><section class="closing"><div class="container closing-inner"><div><span class="eyebrow eyebrow-light">NEWCASTLE HEAD OFFICE</span><h2>Discuss your workplace matter.</h2><p>29 Bird Street, Newcastle, KwaZulu-Natal · +27 34 312 7592</p></div><a class="btn btn-gold" href="/contact/?area=labour">Contact the Firm →</a></div></section></main>'
    dest = ROOT / p["slug"] / "index.html"
    dest.parent.mkdir(parents=True, exist_ok=True)
    dest.write_text(head+shared_body_start+body+shared_body_end, encoding="utf-8")
    print(dest.relative_to(ROOT))
